import{_ as a}from"./chunks/webmcp.AtPcCTXa.js";import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.CfwCq2QB.js";const u=JSON.parse('{"title":"网页工具（WebMCP）","description":"","frontmatter":{},"headers":[],"relativePath":"features/webmcp.md","filePath":"features/webmcp.md"}'),l={name:"features/webmcp.md"};function s(c,e,n,d,p,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="网页工具-webmcp" tabindex="-1">网页工具（WebMCP） <a class="header-anchor" href="#网页工具-webmcp" aria-label="Permalink to &quot;网页工具（WebMCP）&quot;">​</a></h1><p>一句话：自动列出网页通过 WebMCP 注册的工具（含 iframe），AI 可以调用它们完成任务；侧边栏「网页工具」页可以查看每个工具的说明并手动执行（方便调试网页的 WebMCP 实现）。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><p>WebMCP 目前是 Chrome 的实验功能：</p><ol><li>使用 <strong>Chrome 150 及以上</strong></li><li>打开 <code>chrome://flags</code>，搜索「<strong>WebMCP for testing</strong>」并启用</li><li>重启浏览器</li></ol><p>未开启时，弹窗「功能」页的「查看工具」按钮为禁用态并说明原因；Firefox 暂不支持。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>打开提供了工具的网页，侧边栏切到「网页工具」页：</p><ul><li>每个工具一张卡片：工具名、<strong>只读</strong>或<strong>可能修改数据</strong>标签（来自 iframe 的会额外标注）、说明</li><li>展开卡片可以按参数 Schema 生成的模板填参数，点「执行」，结果或错误显示在下方</li><li>顶部会提示工具数量，右侧可「重新检测」（单页应用可能随时注册 / 注销工具）</li><li>浏览器没开 WebMCP、页面读取不到、没有工具、检测中，四种情况各有说明页告诉你原因和处理方式</li></ul><p>更省事的用法是直接在「对话」页描述需求，比如「帮我搜一下红色的 T 恤」，AI 会自动调用网页工具完成。</p><img src="'+a+'" alt="侧边栏「网页工具」页：演示商店注册的 3 个工具卡片（search_products / get_product_details / add_to_cart，带只读或可能修改数据标签），search_products 已执行并返回商品 JSON" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：侧边栏「网页工具」页——工具卡片与只读 / 可能修改数据标签，search_products 已执行并返回结果。</em></p><h2 id="执行前确认" tabindex="-1">执行前确认 <a class="header-anchor" href="#执行前确认" aria-label="Permalink to &quot;执行前确认&quot;">​</a></h2><p>网页提供、且<strong>未声明为只读</strong>的工具（可能提交表单、下单等），执行前会先弹卡片让你确认，可以「允许执行」或「拒绝」。这一保护默认开启，也可以在设置页「AI 助手」里关掉（不建议）。</p><h2 id="给网页开发者的说明" tabindex="-1">给网页开发者的说明 <a class="header-anchor" href="#给网页开发者的说明" aria-label="Permalink to &quot;给网页开发者的说明&quot;">​</a></h2><p>网页通过 <code>document.modelContext</code> 注册工具即可被 DevGo 发现；参数 Schema 会用于生成填参模板。用「网页工具」页手动执行可以方便地调试你的 WebMCP 实现，不需要自己写调用代码。</p>',16)])])}const b=t(l,[["render",s]]);export{u as __pageData,b as default};
